import shutil
import sys

# Add the current directory to path to import our modules
sys.path.insert(0, '.')

# Mock model that tracks what save_pretrained was called with
class MockModel:
    def __init__(self):
        self.calls = []

    def save_pretrained(self, output_dir, safe_serialization=False):
        self.calls.append((output_dir, safe_serialization))
        os.makedirs(output_dir, exist_ok=True)
        if safe_serialization:
            with open(os.path.join(output_dir, "model.safetensors"), "w") as f:
                f.write("safetensors")
        else:
            with open(os.path.join(output_dir, "pytorch_model.bin"), "w") as f:
                f.write("pytorch")

# Test the actual export logic from export.py
print("Testing the export logic that exports to both formats...")

# Clean up
if os.path.exists("test_output"):
    shutil.rmtree("test_output")

# Simulate what happens in export.py
model = MockModel()
args_format = "huggingface"
output_dir = "test_output"

# This is the logic from our modified export.py
if args_format == "huggingface":
    other_format = "safetensors"
elif args_format == "safetensors":
    other_format = "huggingface"

# Mock get_exporter
class MockHuggingfaceExporter:
    def export(self, model, output_dir, **kwargs):
        model.save_pretrained(output_dir, safe_serialization=False)

class MockSafetensorsExporter:
    def export(self, model, output_dir, **kwargs):
        model.save_pretrained(output_dir, safe_serialization=True)

# Export to the requested format
if args_format == "huggingface":
    exporter = MockHuggingfaceExporter()
elif args_format == "safetensors":
    exporter = MockSafetensorsExporter()

exporter.export(model, output_dir)
print(f"Exported to {args_format} format")

# Also export to the other format
if other_format:
    if other_format == "huggingface":
        other_exporter = MockHuggingfaceExporter()
    elif other_format == "safetensors":
        other_exporter = MockSafetensorsExporter()

    # Export to the same directory
    other_exporter.export(model, output_dir)
    print(f"Also exported to {other_format} format")

print(f"Model exported to {output_dir} with both formats")

# Check what was called
print(f"\nsave_pretrained was called {len(model.calls)} times:")
for i, (out_dir, safe) in enumerate(model.calls):
    print(f"  Call {i+1}: output_dir={out_dir}, safe_serialization={safe}")

# Check what files were created
print(f"\nFiles created in {output_dir}:")
for root, dirs, files in os.walk(output_dir):
    for file in files:
        print(f"  {file}")

# Clean up
shutil.rmtree("test_output")
print("\nTest completed.")"}}
